          "Els dos grups de sisè van empatar a dos dimecres a la pista de l’escola. El diari escolar explicarà el partit amb una crònica de la Clara i l’Omar, dos alumnes de l’equip de redacció. La Inés va marcar els dos gols del seu grup: el primer va igualar el marcador a un i el segon va arribar quan perdien per dos a un. Les notes de la Clara seguien les seves curses des de la banda.",
          "En acabar, la Inés va demanar que es fixessin també en Nil. Poc abans del segon gol, ell havia recuperat una pilota al costat de la línia lateral. Dos rivals s’acostaven i, en comptes de continuar corrent entre ells, va passar cap a l’espai per on avançava la Inés. La va avisar amb un crit. Ella va rebre la pilota sense aturar-se i es va poder acostar a la porteria abans de xutar.",
          "L’Omar havia canviat de lloc durant la segona part per anotar què passava prop de la Lia, la portera. Amb l’empat ja establert, un xut rival anava cap a un racó. La Lia el va desviar amb una mà i va caure de genolls. La pilota va sortir fora. No hi va haver més gols abans del final. «Des del meu costat semblava que entrava», va explicar la Inés, que encara era lluny d’aquella porteria.",
          "La crònica obre amb el resultat i la seqüència dels gols. Després reconstrueix el segon gol amb la passada d’en Nil i dedica un paràgraf a l’aturada de la Lia. Per redactar-la, la Clara va ajuntar les seves notes amb les de l’Omar i va parlar amb els tres jugadors. En Nil no recordava el minut exacte de la passada; l’article la situa abans del segon gol, sense afegir-hi un minut que ningú no havia apuntat.",
          "L’Omar va portar dues fotografies a la taula de la redacció, instal·lada aquell dia sota el til·ler. L’una mostrava la Inés després de marcar; a l’altra, la Lia s’aixecava amb un genoll cobert de pols. La Clara havia pensat reservar tot l’espai per al segon gol, però va fer lloc per a totes dues. El peu de la segona imatge explica quin xut acabava d’aturar la portera.",
          "Els primers lectors van buscar els seus noms a la prova del diari. La Lia va anar directament a la seva fotografia. En Nil va llegir el paràgraf de la passada i va assenyalar a la Inés el forat que havia vist des de la banda. Mentre discutien on havia estat cadascú, una pilota va passar rodolant al costat de la taula. La Clara va apartar la llibreta i la va tornar amb el peu."
