          "Firmo esta reseña como Clara, una de las alumnas que preparan el periódico escolar con Omar. Ayer vimos en la escuela La maleta de la farera, una obra del grupo de teatro del barrio. Elia, la protagonista, encuentra una maleta cerrada en la entrada de un faro. Junto al asa hay un billete de barco al que le falta el nombre del viajero. Quiere averiguar a quién debe devolverla antes de marcharse del lugar.",
