        "title": "Una crítica sin abrir la maleta",
        "summary": "Una crítica teatral distingue lo observado de los gustos y decide cuánto contar a un público que aún no conoce la obra.",
        "paragraphs": [
          "Firmo esta reseña como Clara, una de las alumnas que preparan el periódico escolar con Omar. Ayer asistimos en la escuela a La maleta de la farera, una obra del grupo de teatro del barrio. Elia encuentra una maleta cerrada a la entrada de un faro. Del asa cuelga un billete de barco, pero la parte donde debía figurar el nombre del viajero está arrancada. Antes de abandonar el faro, quiere averiguar a quién puede devolverla.",
          "Tres cajas, una silla y una lámpara componen el escenario. Las cajas forman primero unos escalones y luego un muelle. La actriz cambia su forma de caminar al pasar de un lugar al otro; ese movimiento me ayudó a imaginar el espacio más que cualquier objeto nuevo. Omar se quedó con el sonido del mar. En el saludo final vimos a una actriz llevando los papeles que había movido detrás de una tela, y entendimos de dónde salían aquellas olas. El programa no describía esos trucos. Los fuimos entendiendo desde la butaca y comentamos después cuáles habían pasado inadvertidos al principio.",
          "La escena que más discutimos fue una pausa anterior a la apertura de la maleta. Elia la acerca, suelta el cierre y retira la mano. Mira después el billete antes de volver a tocarla. A mí me hizo seguir cada gesto, como si el contenido pudiera adivinarse en su cara. Omar se removió en la silla: llevaba un rato esperando que la abriera. Los dos recordamos aquella secuencia, aunque el mismo retraso despertó mi curiosidad y agotó parte de la suya.",
          "En su comentario para el periódico, Omar había escrito que durante la pausa «no ocurría nada». Le señalé la mano y la mirada hacia el billete. Volvió a escribir: «Los gestos se alargaron más de lo que yo necesitaba para sentir intriga». Me pareció una frase más cercana a lo que me había contado al salir. El movimiento era visible para ambos; la duración que cada uno disfrutaba era una cuestión distinta.",
          "Mi borrador tenía otro problema: explicaba qué había dentro de la maleta y cómo encajaba con una pista anterior. Omar tapó aquellas líneas con la mano. «Imagínate que lo leemos antes de entrar», dijo. Las retiré y mantuve el problema inicial del viajero. Para comentar la interpretación de Elia podía describir sus dudas sin desvelar su descubrimiento. El detalle que prueba una opinión sobre la actriz no tiene por qué ser el que resuelve el misterio.",
          "Recomiendo la obra a quienes disfrutan siguiendo pistas y viendo transformarse un escenario sencillo. Sus momentos de espera pueden pesar a quien prefiera persecuciones rápidas. El silencio hizo que el ruido del cierre sonara enorme para mí; Omar habría agradecido llegar antes a ese ruido. Su comentario aparecerá junto a esta reseña. Cuando me devolvió el borrador corregido, dio dos golpecitos sobre las líneas retiradas, como si llamara a la maleta. Esta vez la dejé cerrada."
        ],
